import{t as e}from"./utils-COoNfFoj.js";var t={slug:`hanna-gets-hired`,influencerName:`Hanna Gets Hired`,influencerHandle:`@hannagetshired`,influencerAvatarUrl:`${e}/hanna-gets-hired-avatar.png`,heroDescription:`I created this networking CRM so every professional connection you make actually advances your career. I built it entirely with Perplexity Computer. I brought the idea, and it handled all the coding and technical decisions. You can try my tool below, or use the same prompt to build and customize your own!`,assetTitle:`Keep In Touch`,screenshotUrl:`${e}/hanna-gets-hired.png`,remixUrl:`https://www.perplexity.ai/computer/a/keep-in-touch-m4kZ4iUQRhKsSFuDoBpqLQ`,promptTitle:`Try Hanna's prompt`,promptText:`Build me a personal networking CRM web app called “Keep in Touch” to power my job search—a relationship-first tool where I can track contacts, log conversations, manage opportunities, and generate AI-drafted outreach that solves the cold-start, blank-page problem. Before building, run a research sub-agent on current networking best practices for job seekers (including outreach cadence, message framing, follow-up timing, and warm vs. cold approaches). Bake these findings into the app’s intelligence layer so its guidance, suggested next steps, and drafted outreach reflect what actually works in today’s market. Include a resume-upload onboarding flow that auto-fills my profile, along with core pages for Contacts, Opportunities, Profile, and a Digest dashboard. Also include working integrations with Gmail and Google Calendar, so drafts can be saved directly to Gmail and outreach can suggest real meeting times based on my calendar availability. Start with an empty database so I can populate it with my own contacts from day one.`};export{t as default};
